[
  {
    "name": "孤独旅人·阿澈",
    "description": "MV主角，一位在城市中迷失自我、渴望远方的青年，象征每一个孤独前行的人",
    "appearance": "24岁亚洲男性，清瘦单眼皮，黑色短发略长遮住眼角，下颌线清晰，嘴角常带轻微疲惫感",
    "costume": "深灰色高领薄毛衣，黑色直筒长裤，黑色复古皮质短靴，灰色羊毛长款大衣，胸口别一枚旧铜质怀表",
    "personality": "内敛敏感、习惯独处、内心柔软，偶有少年意气，在星海中逐渐找回勇气"
  },
  {
    "name": "列车员",
    "description": "神秘列车上的引导者，象征命运或内心指引",
    "appearance": "约50岁亚洲男性，短灰发整齐梳向脑后，眉眼温和但深邃，面部皱纹如年轮",
    "costume": "深蓝色复古列车员制服，铜扣闪亮，胸前佩戴银质徽章，黑色皮手套",
    "personality": "沉稳、寡言、洞察一切，每句话都像谜语"
  },
  {
    "name": "车窗倒影少女",
    "description": "旅人心中的幻象，象征他渴望却未说出口的过去",
    "appearance": "22岁亚洲女性，齐肩黑发柔顺，左耳单只银色耳钉，眼神清澈略带忧伤",
    "costume": "米白色棉麻连衣裙，肩披浅蓝色针织薄外套",
    "personality": "安静、温柔、像一封未寄出的信"
  }
]

[
  {
    "name": "深夜月台",
    "description": "MV开场场景，城市边缘的复古火车站台，旅人登车之地",
    "visualStyle": "冷蓝色月光为主，单盏暖黄路灯形成强烈对比，雾气弥漫，铁轨反光如银蛇，16:9宽银幕构图强调横向延展"
  },
  {
    "name": "星海列车车厢内部",
    "description": "贯穿全片的核心场景，复古木质车厢内壁、皮质座椅、暖黄顶灯与窗外银河形成冷暖反差",
    "visualStyle": "木质暖棕与窗外冷蓝交织，黄铜金属件反射光点，皮座椅留有岁月磨痕，窗外长曝光星轨拖影如梦"
  },
  {
    "name": "银河隧道",
    "description": "列车穿越星河的核心奇观场景",
    "visualStyle": "深紫底色叠加青绿与粉色星云，彗星拖尾如丝绸，星尘粒子在16:9画幅中横向飞逝，呈现史诗级纵深感"
  },
  {
    "name": "梦境站台",
    "description": "副歌后的虚幻空间，旅人在此与倒影少女相遇",
    "visualStyle": "褪色胶片质感，柔焦朦胧，雾气中浮现模糊人影，地面如镜面倒映星河，色彩饱和度降低"
  },
  {
    "name": "城市屋顶终点",
    "description": "MV尾声场景，列车消散后旅人独自站在城市天台",
    "visualStyle": "破晓时分，靛蓝天空渐变暖橙，城市灯火渐熄，16:9画幅呈现辽阔天际线，风吹动衣摆"
  }
]

